mapper.sql:
SELECT SBJCT.SBJCT_ID , SBJCT.SBJCT_YR , SBJCT.SBJCT_SMSTR , SBJCT.SMSTR_CHRT_ID , ORG.ORG_ID , ORG.ORGNM , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , SBJCT.CRDTS , SBJCT.CRCLMN_NO /* 교과목번호 */ , NVL(SBJCT_ADM.COPROF_USERNM, '-') AS COPROF_USERNM /* 공동교수 */ , NVL(SBJCT_ADM.ASSI_USERNM, '-') AS ASSI_USERNM /* 조교 */ , NVL(SBJCT_ADM.TUT_USERNM, '-') AS TUT_USERNM /* 튜터 */ , (CASE WHEN PLANDOC.LCTR_PLANDOC_ID IS NULL THEN 'N' ELSE 'Y' END) AS LSNPLANYN FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = CHRT.ORG_ID LEFT JOIN TB_LMS_LCTR_PLANDOC PLANDOC ON PLANDOC.SBJCT_ID = SBJCT.SBJCT_ID LEFT JOIN ( SELECT T1.SBJCT_ID , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'PROF' THEN T1.USER_ID END) AS PROF_ID , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'PROF' THEN T2.USERNM END) AS PROF_USERNM , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'COPROF' THEN T2.USERNM END) AS COPROF_USERNM , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'ASSI' THEN T2.USERNM END) AS ASSI_USERNM , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'TUT' THEN T2.USERNM END) AS TUT_USERNM FROM TB_LMS_SBJCT_ADM T1 JOIN TB_LMS_USER T2 ON T2.USER_ID = T1.USER_ID GROUP BY T1.SBJCT_ID ) SBJCT_ADM ON SBJCT_ADM.SBJCT_ID = SBJCT.SBJCT_ID WHERE 1=1 AND SBJCT.USEYN = 'Y' AND SBJCT.DELYN = 'N' AND SBJCT_ADM.PROF_ID = #{userId} AND SBJCT.SBJCT_YR = #{sbjctYr}
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
AND ORG.ORG_ID = #{orgId}
AND SBJCT.SBJCT_ID = #{sbjctId}

mapper.select:
/* SQL ID : LctrPlandocDAO.lctrPlandocListPaging 설 명 : 강의계획서 목록 페이징 */
SELECT BASE.* , ROW_NUMBER() OVER( ORDER BY BASE.SBJCT_YR DESC , BASE.SBJCT_SMSTR DESC , BASE.ORG_ID , BASE.SBJCT_ID ) AS LINE_NO , COUNT(*) OVER() AS TOTAL_CNT FROM (
) BASE

mapper.update:
/*
SQL ID : LctrPlandocDAO.lctrPlandocModify
설  명  : 강의계획서 수정
*/
UPDATE TB_LMS_LCTR_PLANDOC
SET
	MDFR_ID   = #{mdfrId}
	, MOD_DTTM = FN_DTTM()

		, CRCLMN_OTLN = #{crclmnOtln}


		, LCTR_GOAL = #{lctrGoal}


		, LCTR_OP_GDLN = #{lctrOpGdln}


		, LCTR_OP_PLAN = #{lctrOpPlan}


		, RLTD_SBJCT_CTS = #{rltdSbjctCts}


		, REMAKRS = #{remakrs}


		, PLYR_SHRTCT_KEY_PVSNYN = #{plyrShrtctKeyPvsnyn}


		, SCRPT_PVSNYN = #{scrptPvsnyn}


		, SBTTLS_PVSNYN = #{sbttlsPvsnyn}


		, PLYR_SPD_ADJST_PVSNYN = #{plyrSpdAdjstPvsnyn}

WHERE SBJCT_ID = #{sbjctId}

mapper.insert:
/*
	 SQL ID : LctrPlandocDAO.lctrPlandocRegist
	 설  명  : 강의계획서 등록
*/
INSERT INTO TB_LMS_LCTR_PLANDOC
(
	  LCTR_PLANDOC_ID
	, SBJCT_ID
	, CRCLMN_OTLN
	, LCTR_GOAL
	, LCTR_OP_GDLN
	, LCTR_OP_PLAN
	, RLTD_SBJCT_CTS
	, REMAKRS
	, PLYR_SHRTCT_KEY_PVSNYN
	, SCRPT_PVSNYN
	, SBTTLS_PVSNYN
	, PLYR_SPD_ADJST_PVSNYN
	, RGTR_ID
	, REG_DTTM
	, MDFR_ID
	, MOD_DTTM
)
VALUES
(
	  #{lctrPlandocId}
	, #{sbjctId}
	, #{crclmnOtln}
	, #{lctrGoal}
	, #{lctrOpGdln}
	, #{lctrOpPlan}
	, #{rltdSbjctCts}
	, #{remakrs}
	, NVL(#{plyrShrtctKeyPvsnyn}, 'N')
	, NVL(#{scrptPvsnyn}, 'N')
	, NVL(#{sbttlsPvsnyn}, 'N')
	, NVL(#{plyrSpdAdjstPvsnyn}, 'N')
	, #{rgtrId}
	, FN_DTTM()
	, #{mdfrId}
	, FN_DTTM()
)

