mapper.select:
/* SQL ID : LctrPlandocDAO.profOrgList 설 명 : 교수 운영 기관 목록 */ SELECT DISTINCT ORG.ORG_ID , ORG.ORGNM FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = CHRT.ORG_ID JOIN TB_LMS_SBJCT_ADM ADM ON ADM.SBJCT_ID = SBJCT.SBJCT_ID WHERE 1 = 1 AND SBJCT.USEYN = 'Y' AND SBJCT.DELYN = 'N' AND ADM.SBJCT_ADM_TYCD = 'PROF' AND ADM.USER_ID = #{userId} AND SBJCT.SBJCT_YR = #{sbjctYr}
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
ORDER BY ORG.ORGNM

/* SQL ID : LctrPlandocDAO.profSbjctList 설 명 : 교수 운영 과목 목록 */ SELECT DISTINCT SBJCT.SBJCT_ID , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , SBJCT.CRCLMN_NO FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID JOIN TB_LMS_SBJCT_ADM ADM ON ADM.SBJCT_ID = SBJCT.SBJCT_ID WHERE 1 = 1 AND SBJCT.USEYN = 'Y' AND SBJCT.DELYN = 'N' AND ADM.SBJCT_ADM_TYCD = 'PROF' AND ADM.USER_ID = #{userId} AND SBJCT.SBJCT_YR = #{sbjctYr}
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
AND CHRT.ORG_ID = #{orgId}
ORDER BY SBJCT.SBJCTNM , SBJCT.DVCLAS_NO

mapper.sql:
SELECT SBJCT.SBJCT_ID , SBJCT.SBJCT_YR , SBJCT.SBJCT_SMSTR , SBJCT.SMSTR_CHRT_ID , ORG.ORG_ID , ORG.ORGNM , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE LANG_CD = NVL(#{langCd}, 'ko') AND UP_CD = 'SBJCT_TYCD' AND CD = SBJCT.SBJCT_TYCD) AS SBJCT_TYNM , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE LANG_CD = NVL(#{langCd}, 'ko') AND UP_CD = 'LCTR_GBNCD' AND CD = SBJCT.LCTR_GBNCD) AS LCTR_GBNNM , (SELECT CDNM FROM TB_LMS_CMMN_CD WHERE LANG_CD = NVL(#{langCd}, 'ko') AND UP_CD = 'CMCRS_GBNCD' AND CD = SBJCT.CMCRS_GBNCD) AS CMCRS_GBNNM , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , SBJCT.CRDTS , SBJCT.CRCLMN_NO , NVL(SBJCT_ADM.PROF_USERNM, '-') AS PROF_USERNM , NVL(SBJCT_ADM.COPROF_USERNM, '-') AS COPROF_USERNM , NVL(SBJCT_ADM.TUT_USERNM, '-') AS TUT_USERNM , CASE WHEN PLANDOC.LCTR_PLANDOC_ID IS NULL THEN 'N' ELSE 'Y' END AS LSNPLANYN , PLANDOC.REG_DTTM FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = CHRT.ORG_ID LEFT JOIN TB_LMS_LCTR_PLANDOC PLANDOC ON PLANDOC.SBJCT_ID = SBJCT.SBJCT_ID LEFT JOIN ( SELECT T1.SBJCT_ID , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'PROF' THEN T2.USERNM END) AS PROF_USERNM , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'COPROF' THEN T2.USERNM END) AS COPROF_USERNM , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'TUT' THEN T2.USERNM END) AS TUT_USERNM FROM TB_LMS_SBJCT_ADM T1 JOIN TB_LMS_USER T2 ON T2.USER_ID = T1.USER_ID GROUP BY T1.SBJCT_ID ) SBJCT_ADM ON SBJCT_ADM.SBJCT_ID = SBJCT.SBJCT_ID WHERE 1 = 1 AND SBJCT.USEYN = 'Y' AND SBJCT.DELYN = 'N'
AND SBJCT.SBJCT_YR = #{sbjctYr}
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
AND ORG.ORG_ID = #{orgId}
AND SBJCT.SBJCT_ID = #{sbjctId}
AND SBJCT.SBJCTNM LIKE FN_LIKE_VAL(#{searchValue})

mapper.select:
/* SQL ID : LctrPlandocDAO.admLctrPlandocListPaging 설 명 : 관리자 강의계획서 페이징 목록 */
SELECT BASE.* , ROW_NUMBER() OVER( ORDER BY BASE.SBJCT_YR DESC, BASE.SBJCT_SMSTR DESC, BASE.ORG_ID, BASE.SBJCT_ID ) AS LINE_NO , COUNT(*) OVER() AS TOTAL_CNT FROM (
) BASE

/* SQL ID : LctrPlandocDAO.admOrgList 설 명 : 관리자 기관 목록 */ SELECT DISTINCT ORG.ORG_ID, ORG.ORGNM FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = CHRT.ORG_ID WHERE SBJCT.USEYN = 'Y' AND SBJCT.DELYN = 'N'
AND SBJCT.SBJCT_YR = #{sbjctYr}
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
ORDER BY ORG.ORGNM

/*
	 SQL ID : LctrPlandocDAO.admSbjctList
	 설  명  : 관리자 과목 목록
*/
SELECT DISTINCT SBJCT.SBJCT_ID, SBJCT.SBJCTNM, SBJCT.DVCLAS_NO, SBJCT.CRCLMN_NO
FROM TB_LMS_SBJCT SBJCT
JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID
WHERE SBJCT.USEYN = 'Y'
	AND SBJCT.DELYN = 'N'

	AND SBJCT.SBJCT_YR = #{sbjctYr}


	AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}


	AND CHRT.ORG_ID = #{orgId}

ORDER BY SBJCT.SBJCTNM, SBJCT.DVCLAS_NO

