	, EXAM_OP_AUTH_DLGTNYN = #{examOpAuthDlgtnyn}
	, MDFR_ID = #{mdfrId}
	, MOD_DTTM = FN_DTTM()
WHERE RLTM_EXAM_ID = #{rltmExamId}

mapper.sql:
SELECT SBJCT.SBJCT_ID , SBJCT.SBJCT_YR , SBJCT.SBJCT_SMSTR , SBJCT.SMSTR_CHRT_ID , ORG.ORG_ID , ORG.ORGNM , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , SBJCT.CRDTS , SBJCT.CRCLMN_NO , NVL(SBJCT_ADM.PROF_USERNM, '-') AS PROF_USERNM , NVL(SBJCT_ADM.COPROF_USERNM, '-') AS COPROF_USERNM , NVL(SBJCT_ADM.ASSI_USERNM, '-') AS ASSI_USERNM , NVL(SBJCT_ADM.TUT_USERNM, '-') AS TUT_USERNM , CASE WHEN PLANDOC.LCTR_PLANDOC_ID IS NULL THEN 'N' ELSE 'Y' END AS LSNPLANYN FROM TB_LMS_ATNDLC ATNDLC JOIN TB_LMS_SBJCT SBJCT ON SBJCT.SBJCT_ID = ATNDLC.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = CHRT.ORG_ID LEFT JOIN TB_LMS_LCTR_PLANDOC PLANDOC ON PLANDOC.SBJCT_ID = SBJCT.SBJCT_ID LEFT JOIN ( SELECT ADM.SBJCT_ID , MAX(CASE WHEN ADM.SBJCT_ADM_TYCD = 'PROF' THEN USR.USERNM END) AS PROF_USERNM , MAX(CASE WHEN ADM.SBJCT_ADM_TYCD = 'COPROF' THEN USR.USERNM END) AS COPROF_USERNM , MAX(CASE WHEN ADM.SBJCT_ADM_TYCD = 'ASSI' THEN USR.USERNM END) AS ASSI_USERNM , MAX(CASE WHEN ADM.SBJCT_ADM_TYCD = 'TUT' THEN USR.USERNM END) AS TUT_USERNM FROM TB_LMS_SBJCT_ADM ADM JOIN TB_LMS_USER USR ON USR.USER_ID = ADM.USER_ID GROUP BY ADM.SBJCT_ID ) SBJCT_ADM ON SBJCT_ADM.SBJCT_ID = SBJCT.SBJCT_ID WHERE 1 = 1 AND SBJCT.USEYN = 'Y' AND SBJCT.DELYN = 'N' AND ATNDLC.USER_ID = #{userId} AND ATNDLC.ATNDLC_STSCD = 'APPROVE'
AND SBJCT.SBJCT_YR = #{sbjctYr}
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
AND ORG.ORG_ID = #{orgId}
AND SBJCT.SBJCT_ID = #{sbjctId}

mapper.select:
/* SQL ID : LctrPlandocDAO.stdntLctrPlandocListPaging 설 명 : 학생 강의계획서 목록 페이징 */
SELECT BASE.* , ROW_NUMBER() OVER( ORDER BY BASE.SBJCT_YR DESC , BASE.SBJCT_SMSTR DESC , BASE.ORG_ID , BASE.SBJCT_ID ) AS LINE_NO , COUNT(*) OVER() AS TOTAL_CNT FROM (
) BASE

/* SQL ID : LctrPlandocDAO.stdntOrgList 설 명 : 학생 수강 기관 목록 */ SELECT DISTINCT ORG.ORG_ID , ORG.ORGNM FROM TB_LMS_ATNDLC ATNDLC JOIN TB_LMS_SBJCT SBJCT ON SBJCT.SBJCT_ID = ATNDLC.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = CHRT.ORG_ID WHERE 1 = 1 AND ATNDLC.USER_ID = #{userId} AND ATNDLC.ATNDLC_STSCD = 'APPROVE'
AND SBJCT.USEYN = 'Y' AND SBJCT.DELYN = 'N' AND SBJCT.SBJCT_YR = #{sbjctYr}
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
ORDER BY ORG.ORGNM

/* SQL ID : LctrPlandocDAO.stdntSbjctList 설 명 : 학생 수강과목 목록 */ SELECT DISTINCT SBJCT.SBJCT_ID , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO FROM TB_LMS_ATNDLC ATNDLC JOIN TB_LMS_SBJCT SBJCT ON SBJCT.SBJCT_ID = ATNDLC.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID WHERE 1 = 1 AND ATNDLC.USER_ID = #{userId} AND ATNDLC.ATNDLC_STSCD = 'APPROVE'
AND SBJCT.USEYN = 'Y' AND SBJCT.DELYN = 'N' AND SBJCT.SBJCT_YR = #{sbjctYr}
AND SBJCT.SMSTR_CHRT_ID = #{smstrChrtId}
AND CHRT.ORG_ID = #{orgId}
ORDER BY SBJCT.SBJCTNM , SBJCT.DVCLAS_NO
